function hexByte(v) {
  var s = (v & 0xff).toString(16);
  return s.length < 2 ? '0' + s : s;
}

function int16be(n) {
  var u = n < 0 ? n + 0x10000 : n;
  return [(u >> 8) & 0xff, u & 0xff];
}

function buildFrame(payload) {
  if (payload.length > 255) throw new Error('ARGUMENT: payload too long');
  var len = payload.length;
  var x = len;
  for (var i = 0; i < payload.length; i++) x ^= payload[i];
  var bytes = [0xa5, len].concat(payload, [x & 0xff]);
  var out = '';
  for (var j = 0; j < bytes.length; j++) out += hexByte(bytes[j]);
  return out;
}

function quantizeChannel(v) {
  var x = Number(v);
  if (!isFinite(x)) throw new Error('ARGUMENT: non-finite channel');
  var n = Math.round(x * 10000);
  if (n < -1000 || n > 1000) throw new Error('ARGUMENT: channel out of range');
  return n;
}

function encode(command) {
  var payload;
  if (Array.isArray(command)) {
    if (command.length !== 2) throw new Error('ARGUMENT: XY command needs 2 channels');
    var a = quantizeChannel(command[0]);
    var b = quantizeChannel(command[1]);
    payload = [0x10].concat(int16be(a), int16be(b));
  } else if (command && typeof command === 'object') {
    if (command.op === 'lift') {
      if (command.position === 'up') payload = [0x20, 1];
      else if (command.position === 'down') payload = [0x20, 0];
      else throw new Error('ARGUMENT: lift position');
    } else if (command.op === 'grip') {
      if (command.state === 'closed') payload = [0x21, 1];
      else if (command.state === 'open') payload = [0x21, 0];
      else throw new Error('ARGUMENT: grip state');
    } else {
      throw new Error('OPCODE: unknown op');
    }
  } else {
    throw new Error('ARGUMENT: unsupported command');
  }
  return buildFrame(payload);
}

var ERROR_NAMES = {
  1: 'FRAME',
  2: 'CHECKSUM',
  3: 'NOT_READY',
  4: 'LIMIT',
  5: 'OPCODE',
  6: 'ARGUMENT',
  7: 'COLLISION'
};

function readInt16(p, i) {
  var u = (p[i] << 8) | p[i + 1];
  return u >= 0x8000 ? u - 0x10000 : u;
}

function decode(rawReply) {
  if (typeof rawReply !== 'string') throw new Error('FRAME: reply not string');
  var s = rawReply.trim().toLowerCase();
  if (s.length % 2 !== 0 || !/^[0-9a-f]*$/.test(s)) throw new Error('FRAME: bad hex');
  var b = [];
  for (var i = 0; i < s.length; i += 2) b.push(parseInt(s.substr(i, 2), 16));
  if (b.length < 4) throw new Error('FRAME: too short');
  if (b[0] !== 0xa5) throw new Error('FRAME: bad sync');
  var len = b[1];
  if (len < 2) throw new Error('FRAME: payload too short');
  if (b.length !== len + 3) throw new Error('FRAME: length mismatch');
  var x = 0;
  for (var k = 1; k <= 1 + len; k++) x ^= b[k];
  if (x !== b[len + 2]) throw new Error('CHECKSUM: mismatch');
  var p = b.slice(2, 2 + len);
  var status = p[0];
  var op = p[1];
  if (status !== 0) {
    throw new Error((ERROR_NAMES[status] || 'UNKNOWN') + ': device status ' + status + ' op ' + op);
  }
  if (op === 0x10) {
    if (len < 7) throw new Error('FRAME: step reply too short');
    var fa = readInt16(p, 2) / 10000;
    var fb = readInt16(p, 4) / 10000;
    return { applied: [fa, fb], limited: (p[6] & 1) === 1 };
  }
  if (op === 0x20) {
    if (len < 4) throw new Error('FRAME: lift reply too short');
    if (p[2] !== 0 && p[2] !== 1) throw new Error('ARGUMENT: bad lift position');
    return { applied: { op: 'lift', position: p[2] === 1 ? 'up' : 'down' }, limited: (p[3] & 1) === 1 };
  }
  if (op === 0x21) {
    if (len < 4) throw new Error('FRAME: grip reply too short');
    if (p[2] !== 0 && p[2] !== 1) throw new Error('ARGUMENT: bad grip state');
    return { applied: { op: 'grip', state: p[2] === 1 ? 'closed' : 'open' }, limited: (p[3] & 1) === 1 };
  }
  throw new Error('OPCODE: unexpected reply opcode ' + op);
}

