function control(state) {
  var tip = state.tip;
  var target = state.target;
  var ex = target[0] - tip[0];
  var ey = target[1] - tip[1];
  var err = Math.sqrt(ex * ex + ey * ey);
  if (!isFinite(err)) return { action: 'stop', reason: 'non-finite error' };
  if (err <= state.tolerancePx) return { action: 'verify' };
  if (state.maxActions !== null && state.maxActions !== undefined && state.step >= state.maxActions) {
    return { action: 'stop', reason: 'action budget exhausted' };
  }

  var h = state.history || [];
  var start = h.length > 12 ? h.length - 12 : 0;
  var q00 = 0, q01 = 0, q11 = 0;
  var m00 = 0, m01 = 0, m10 = 0, m11 = 0;
  for (var i = start; i < h.length; i++) {
    var e = h[i];
    if (!e || !e.applied || !e.delta) continue;
    var a0 = Number(e.applied[0]), a1 = Number(e.applied[1]);
    var d0 = Number(e.delta[0]), d1 = Number(e.delta[1]);
    if (!isFinite(a0) || !isFinite(a1) || !isFinite(d0) || !isFinite(d1)) continue;
    q00 += a0 * a0; q01 += a0 * a1; q11 += a1 * a1;
    m00 += d0 * a0; m01 += d0 * a1;
    m10 += d1 * a0; m11 += d1 * a1;
  }

  // probe channels that have not been excited enough
  if (q00 < 1e-5) return { action: 'move', u: [0.05, 0] };
  if (q11 < 1e-5) return { action: 'move', u: [0, 0.05] };

  var reg = 1e-9;
  q00 += reg; q11 += reg;
  var det = q00 * q11 - q01 * q01;
  if (!isFinite(det) || Math.abs(det) < 1e-12) return { action: 'move', u: [0.05, 0] };
  // Qinv
  var i00 = q11 / det, i01 = -q01 / det, i11 = q00 / det;
  // J = M * Qinv  (2x2), rows are pixel axes, cols are channels
  var j00 = m00 * i00 + m01 * i01;
  var j01 = m00 * i01 + m01 * i11;
  var j10 = m10 * i00 + m11 * i01;
  var j11 = m10 * i01 + m11 * i11;
  var jdet = j00 * j11 - j01 * j10;
  if (!isFinite(jdet) || Math.abs(jdet) < 1e-3) {
    // poorly conditioned: excite the less-known direction
    return { action: 'move', u: [0, 0.05] };
  }

  // desired pixel displacement, damped and capped
  var dpx = ex, dpy = ey;
  var dnorm = Math.sqrt(dpx * dpx + dpy * dpy);
  var cap = 20;
  if (dnorm > cap) { dpx = dpx * cap / dnorm; dpy = dpy * cap / dnorm; }
  dpx *= 0.5; dpy *= 0.5;

  // u = J^{-1} dp
  var k00 = j11 / jdet, k01 = -j01 / jdet, k10 = -j10 / jdet, k11 = j00 / jdet;
  var ua = k00 * dpx + k01 * dpy;
  var ub = k10 * dpx + k11 * dpy;
  if (!isFinite(ua) || !isFinite(ub)) return { action: 'move', u: [0.05, 0] };

  var un = Math.sqrt(ua * ua + ub * ub);
  if (un > 0.1) { ua = ua * 0.1 / un; ub = ub * 0.1 / un; }
  ua = Math.max(-0.1, Math.min(0.1, ua));
  ub = Math.max(-0.1, Math.min(0.1, ub));
  return { action: 'move', u: [ua, ub] };
}
